import 'ukumari_animation.dart';

/// Origin of the biodiversity advisor response.
enum GuideResponseSource {
  /// Generated by the built-in domain knowledge engine (offline-capable).
  localKnowledge,

  /// Generated by the cloud AI model (Gemini REST adapter).
  aiModel,
}

/// Immutable value object representing Ukumari's answer to a user interaction.
class GuideResponse {
  const GuideResponse({
    required this.replyText,
    required this.primaryAnimation,
    required this.followUpSuggestions,
    required this.source,
    this.topicTitle,
    this.audioAssetKey,
  });

  /// Spoken and displayed response in neutral Spanish.
  final String replyText;

  /// Skeletal animation clip to trigger while delivering the response.
  final UkumariAnimation primaryAnimation;

  /// Follow-up questions the user can tap to continue the conversation.
  final List<String> followUpSuggestions;

  /// Indicates whether the response came from local knowledge or the AI model.
  final GuideResponseSource source;

  /// Optional topic title badge.
  final String? topicTitle;

  /// Optional pre-rendered neural studio audio key (`saludo_inicial`, `como_llegar`, `que_hay`).
  final String? audioAssetKey;
}
